const REVIEW_MARKER = "<!--adversarial-review-auto-->";
const FEEDBACK_MARKER = "<!--adversarial-review-feedback-->";

const MAX_REREVIEW_CYCLES = 2;
// Absolute per-parent injection cap, monotonic for the process lifetime.
// The per-message budget above is reset by any user-role message without our
// feedback marker, including synthetic ones (compaction, other plugins), so
// it alone cannot prove termination. This counter only ever increments at
// send time, making "can never loop forever" true by mechanism.
const MAX_TOTAL_INJECTIONS = 10;
const MAX_FEEDBACK_CHARS = 8000;
// First line of every review_status answer: the version this process runs,
// in the spec form opencode.json pins, so a caller can compare the two.
// Labelled "plugin:", a word no review state uses, so it never reads as a
// review in progress.
const RUNNING_LINE = `plugin: ${PKG_NAME}@${PKG_VERSION || "unknown"}`;

// A review session can go idle WITHOUT a verdict: some orchestrator agents
// launch the critics as background tasks and end their turn immediately,
// which used to be finalized as a verdict-less "done" with the launch
// acknowledgment captured as the report. Verdict-less idles get nudged back
// to work instead, capped so a hopeless orchestrator still terminates.
const MAX_VERDICT_NUDGES = 2;

const DEFAULT_MAX_DIFF_LINES = 2000;
// A lane's committed range is larger than one coding turn's diff.
const DEFAULT_BRANCH_MAX_DIFF_LINES = 6000;
const MAX_BRANCH_REPORT_CHARS = 32000;
const DEFAULT_IDLE_DEBOUNCE_MS = 1000;
// Half-time check: a review still in its mechanical gates at this point is
// stuck in setup (observed: hunting type packages outside the project) and
// is steered straight to the critics. A review whose critics are running
// when the deadline hits gets one extension of half the budget instead of
